package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen0Test {

    private Element element;

    @Before
    public void setUp() {
        element = new Element(Tag.valueOf("div"), "http://example.com");
    }

    @Test(expected = NullPointerException.class)
    public void append_nullHtml_throwsNullPointerException() {
        element.append(null);
    }

    @Test
    public void append_validHtml_appendsNodes() {
        String html = "<p>Hello</p><span>World</span>";
        element.append(html);
        Elements children = element.children();
        assertEquals(2, children.size());
        assertEquals("p", children.get(0).tagName());
        assertEquals("span", children.get(1).tagName());
    }

    @Test
    public void append_emptyHtml_doesNotAlterElement() {
        String html = "";
        element.append(html);
        assertEquals(0, element.children().size());
    }

    @Test
    public void append_singleTextNode_addsTextNode() {
        String html = "Hello";
        element.append(html);
        assertEquals(1, element.children().size());
        assertEquals("Hello", element.child(0).text());
    }

    @Test
    public void append_singleElementNode_addsElementNode() {
        String html = "<span>Test</span>";
        element.append(html);
        assertEquals(1, element.children().size());
        assertEquals("span", element.child(0).tagName());
        assertEquals("Test", element.child(0).text());
    }

    @Test
    public void append_multipleNodes_addsAllNodes() {
        String html = "<div>1</div><div>2</div><div>3</div>";
        element.append(html);
        assertEquals(3, element.children().size());
        assertEquals("1", element.child(0).text());
        assertEquals("2", element.child(1).text());
        assertEquals("3", element.child(2).text());
    }

    @Test
    public void append_withExistingNodes_preservesExistingNodes() {
        Element child1 = new Element(Tag.valueOf("p"), "http://example.com");
        child1.appendChild(Jsoup.parseBodyFragment("Initial").body().child(0));
        element.appendChild(child1);

        String html = "<div>Added</div>";
        element.append(html);

        assertEquals(2, element.children().size());
        assertEquals("p", element.child(0).tagName());
        assertEquals("Initial", element.child(0).text());
        assertEquals("div", element.child(1).tagName());
        assertEquals("Added", element.child(1).text());
    }

    @Test
    public void append_invalidHtml_doesNotAlterElement() {
        String html = "<div><p>Unclosed";
        element.append(html);
        assertEquals(1, element.children().size());
        assertEquals("div", element.child(0).tagName());
        assertEquals("Unclosed", element.child(0).text());
    }
}
